#include "native/media_assembly_scene.hpp"
#include "core/data/json.hpp"
#include <cmath>
#include <fstream>
#include <iostream>
namespace {unsigned checks{};void check(bool b,const char*s){++checks;if(!b)throw std::runtime_error(s);}void run(const ehud::data::Json&j){using endfield::native::MediaAssemblyMotion;MediaAssemblyMotion motion;motion.revealDrawer(1,true);motion.closeMedia(1,true);motion.scrollInline(13.25,0,false);motion.scrollInline(217.125,1,true);double maxError{};for(const auto&row:j["rows"].array()){const auto kind=row["kind"].integer();const auto phase=row["phase"].number(),t=1+phase*(kind==2?.08:.16);const auto actual=kind==0?motion.drawerOpacity(t):kind==1?motion.closeOpacity(t):motion.inlineOffset(t);maxError=std::max(maxError,std::abs(actual-row["value"].number()));check(std::abs(actual-row["value"].number())<2e-5,"Finite motion matches genuine original CA presentation");}check(!motion.requiresFrames(2)&&motion.inlineOffset(2)==217.125&&motion.drawerOpacity(2)==1&&motion.closeOpacity(2)==0,"Finite tracks settle without idle work");const auto previous=motion.inlineOffset(1.04);motion.scrollInline(400,1.04,true);check(motion.inlineOffset(1.04)==previous,"Interrupted scroll begins at visible source presentation");motion.settle();check(motion.inlineOffset(1.04)==400&&!motion.requiresFrames(1.04)&&motion.closeOpacity(1.04)==0,"Hide settles scroll and cancels finite close");motion.revealDrawer(3,false);motion.closeMedia(3,false);motion.scrollInline(7.125,3,false);check(motion.drawerOpacity(3)==1&&motion.closeOpacity(3)==0&&motion.inlineOffset(3)==7.125&&!motion.requiresFrames(3),"Reduced motion applies source model endpoints");for(double invalid:{INFINITY,NAN}){bool rejected{};try{motion.scrollInline(invalid,4,true);}catch(const std::invalid_argument&){rejected=true;}check(rejected&&motion.inlineOffset(4)==7.125,"Invalid offset preserves retained track");}std::cout<<"maximumOriginalCAError="<<maxError<<'\n';}}
int main(int argc,char**argv){try{check(argc==2,"Pass original Media Assembly motion fixture");std::ifstream f(argv[1]);check(bool(f),"Open original source motion fixture");run(ehud::data::Json::parse(std::string(std::istreambuf_iterator<char>(f),{}),128*1024));std::cout<<"PASS "<<checks<<" Media Assembly motion checks\n";return 0;}catch(const std::exception&e){std::cerr<<"FAIL after "<<checks<<": "<<e.what()<<'\n';return 1;}}
